function PhotoBooth() {
  const [photos, setPhotos] = useState([]);
  const [preview, setPreview] = useState(null);
  const [caption, setCaption] = useState('');
  const [username, setUsername] = useState('');
  const [uploading, setUploading] = useState(false);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [expandedCaptions, setExpandedCaptions] = useState({});
  const [selectedPhoto, setSelectedPhoto] = useState(null);

  useEffect(() => {
    const savedUsername = localStorage.getItem('dogForumUsername');
    if (savedUsername) {
      setUsername(savedUsername);
    }
    
    // Initialize user ID if not exists
    if (!localStorage.getItem('dogForumUserId')) {
      const userId = `user_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
      localStorage.setItem('dogForumUserId', userId);
    }
  }, []);

  useEffect(() => {
    const q = query(
      collection(db, 'photos'),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const photosData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
        likedBy: doc.data().likedBy || []
      }));
      setPhotos(photosData);
    });

    return () => unsubscribe();
  }, []);

  const onDrop = useCallback((acceptedFiles) => {
    const file = acceptedFiles[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setPreview({
          url: e.target.result,
          file: file
        });
      };
      reader.readAsDataURL(file);
    }
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/*': ['.jpeg', '.jpg', '.png', '.gif', '.webp']
    },
    maxFiles: 1
  });

  const handleUpload = async () => {
    if (!preview || !username.trim()) {
      alert('Please enter your name before uploading');
      return;
    }

    if (caption.length > 500) {
      alert('Caption must be 500 characters or less');
      return;
    }

    setUploading(true);
    try {
      localStorage.setItem('dogForumUsername', username);
      
      // Create FormData for Cloudinary upload
      const formData = new FormData();
      formData.append('file', preview.file);
      formData.append('upload_preset', 'dog_forum_uploads');
      formData.append('folder', 'dog-forum');
      
      // Upload to Cloudinary
      const response = await fetch(
        `https://api.cloudinary.com/v1_1/dj7nrved6/image/upload`,
        {
          method: 'POST',
          body: formData
        }
      );
      
      if (!response.ok) {
        // Fallback to demo account if custom account not set up
        const demoFormData = new FormData();
        demoFormData.append('file', preview.file);
        demoFormData.append('upload_preset', 'ml_default');
        
        const demoResponse = await fetch(
          'https://api.cloudinary.com/v1_1/demo/image/upload',
          {
            method: 'POST',
            body: demoFormData
          }
        );
        
        if (!demoResponse.ok) {
          throw new Error('Failed to upload image');
        }
        
        const demoData = await demoResponse.json();
        var imageUrl = demoData.secure_url;
      } else {
        const data = await response.json();
        imageUrl = data.secure_url;
      }
      
      // Save to Firestore
      await addDoc(collection(db, 'photos'), {
        url: imageUrl,
        caption: caption || 'My furry friend!',
        authorName: username,
        createdAt: serverTimestamp(),
        likes: 0,
        likedBy: []
      });
      
      setPreview(null);
      setCaption('');
      setShowUploadModal(false);
      alert('Photo uploaded successfully!');
    } catch (error) {
      console.error('Error uploading photo:', error);
      alert('Failed to upload photo. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const handleCancel = () => {
    setPreview(null);
    setCaption('');
    setShowUploadModal(false);
  };

  const handleRemoveImage = () => {
    setPreview(null);
  };

  const userId = localStorage.getItem('dogForumUserId');

  const handleLike = async (photoId, currentLikes, likedBy = [], event) => {
    event.stopPropagation();
    
    try {
      const photoRef = doc(db, 'photos', photoId);
      if (likedBy.includes(userId)) {
        await updateDoc(photoRef, {
          likes: Math.max(0, currentLikes - 1),
          likedBy: arrayRemove(userId)
        });
      } else {
        await updateDoc(photoRef, {
          likes: currentLikes + 1,
          likedBy: arrayUnion(userId)
        });
      }
    } catch (error) {
      console.error('Error updating like:', error);
    }
  };

  const toggleCaptionExpansion = (photoId, event) => {
    event.stopPropagation();
    setExpandedCaptions(prev => ({
      ...prev,
      [photoId]: !prev[photoId]
    }));
  };

  const openPhotoDetail = (photo) => {
    setSelectedPhoto(photo);
  };

  const closePhotoDetail = () => {
    setSelectedPhoto(null);
  };

  return (
    <PhotoBoothContainer>
      <UploadCard>
        <UploadCardHeader>
          <UploadCardIcon>
            <FaCamera />
          </UploadCardIcon>
          <div>
            <UploadCardTitle>Share Your Photo</UploadCardTitle>
          </div>
        </UploadCardHeader>
        <UploadCardSubtitle>
          Capture and share special moments with your furry friend
        </UploadCardSubtitle>
        <UploadButton onClick={() => setShowUploadModal(true)}>
          <FaUpload /> Upload Photo
        </UploadButton>
      </UploadCard>

      {showUploadModal && (
        <ModalOverlay onClick={(e) => e.target === e.currentTarget && handleCancel()}>
          <ModalContent>
            <ModalHeader>
              <ModalTitle>Share Your Paw-some Photo</ModalTitle>
              <CloseButton onClick={handleCancel}>
                <FaTimes />
              </CloseButton>
            </ModalHeader>
            <ModalBody>
              <GuidelinesSection>
                <GuidelinesTitle>
                  <FaInfoCircle /> Photo Community Guidelines
                </GuidelinesTitle>
                <GuidelinesList>
                  <li>Share photos of your own dogs or with owner's permission</li>
                  <li>Keep content family-friendly and appropriate for all ages</li>
                  <li>No graphic or disturbing content</li>
                  <li>Respect privacy - avoid showing personal information</li>
                  <li>Celebrate the joy and love of our furry friends!</li>
                </GuidelinesList>
              </GuidelinesSection>

              {!preview ? (
                <DropzoneArea {...getRootProps()} $isDragActive={isDragActive}>
                  <input {...getInputProps()} />
                  <UploadIcon>
                    <FaUpload />
                  </UploadIcon>
                  <UploadText>
                    {isDragActive ? 'Drop your photo here!' : 'Click or drag to upload a photo'}
                  </UploadText>
                  <UploadHint>Supports JPG, PNG, GIF up to 10MB</UploadHint>
                  <UploadLimit>⚠️ Only one image can be uploaded at a time</UploadLimit>
                </DropzoneArea>
              ) : (
                <PreviewSection>
                  <PreviewContainer>
                    <PreviewImage src={preview.url} alt="Preview" />
                    <RemoveImageButton onClick={handleRemoveImage}>
                      <FaTimes />
                    </RemoveImageButton>
                  </PreviewContainer>
                  <UsernameInput
                    type="text"
                    placeholder="Your name"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                  />
                  <CaptionInput
                    placeholder="Add a caption about your furry friend... (max 500 characters)"
                    value={caption}
                    onChange={(e) => setCaption(e.target.value.slice(0, 500))}
                    maxLength={500}
                  />
                  <p style={{ fontSize: '0.85rem', color: '#666', marginTop: '-0.5rem', marginBottom: '1rem' }}>
                    {caption.length}/500 characters
                  </p>
                  <ButtonGroup>
                    <Button 
                      className="primary" 
                      onClick={handleUpload}
                      disabled={uploading || !username.trim()}
                    >
                      <FaCamera /> {uploading ? 'Uploading...' : 'Share Photo'}
                    </Button>
                  </ButtonGroup>
                </PreviewSection>
              )}
            </ModalBody>
          </ModalContent>
        </ModalOverlay>
      )}

      {selectedPhoto && (
        <PhotoDetailModal onClick={closePhotoDetail}>
          <PhotoDetailContent onClick={(e) => e.stopPropagation()}>
            <DetailCloseButton onClick={closePhotoDetail}>
              <FaTimes />
            </DetailCloseButton>
            <DetailImage src={selectedPhoto.url} alt={selectedPhoto.caption} />
            <DetailInfo>
              <DetailCaption>{selectedPhoto.caption}</DetailCaption>
              <DetailMeta>
                <PhotoAuthor>
                  <FaPaw /> {selectedPhoto.authorName}
                </PhotoAuthor>
                <LikeButton 
                  $liked={selectedPhoto.likedBy?.includes(userId)}
                  onClick={(e) => handleLike(selectedPhoto.id, selectedPhoto.likes || 0, selectedPhoto.likedBy, e)}
                >
                  <FaHeart />
                  <span>{selectedPhoto.likes || 0}</span>
                </LikeButton>
              </DetailMeta>
            </DetailInfo>
          </PhotoDetailContent>
        </PhotoDetailModal>
      )}
      
      <PhotoGrid>
        {photos.map(photo => {
          const isExpanded = expandedCaptions[photo.id];
          const isLongCaption = photo.caption.length > 100;
          
          return (
            <PhotoCard key={photo.id} onClick={() => openPhotoDetail(photo)}>
              <ExpandIcon>
                <FaExpand />
              </ExpandIcon>
              <PhotoImage src={photo.url} alt={photo.caption} />
              <PhotoInfo>
                <PhotoCaption className={!isExpanded && isLongCaption ? 'truncated' : ''}>
                  {photo.caption}
                </PhotoCaption>
                {isLongCaption && (
                  <SeeMoreButton onClick={(e) => toggleCaptionExpansion(photo.id, e)}>
                    {isExpanded ? 'See less' : 'See more'}
                  </SeeMoreButton>
                )}
                <PhotoMeta>
                  <PhotoAuthor>
                    <FaPaw /> {photo.authorName}
                  </PhotoAuthor>
                  <LikeButton 
                    $liked={photo.likedBy?.includes(userId)}
                    onClick={(e) => handleLike(photo.id, photo.likes || 0, photo.likedBy, e)}
                  >
                    <FaHeart />
                    <span>{photo.likes || 0}</span>
                  </LikeButton>
                </PhotoMeta>
              </PhotoInfo>
            </PhotoCard>
          );
        })}
      </PhotoGrid>
      
      {photos.length === 0 && (
        <div style={{ textAlign: 'center', padding: '4rem', color: '#666' }}>
          <FaCamera style={{ fontSize: '3rem', marginBottom: '1rem', opacity: 0.5 }} />
          <p>No photos yet. Click the + button to share your first photo!</p>
        </div>
      )}
    </PhotoBoothContainer>
  );
}

export default PhotoBooth;